A GHC anti-de Sitter spacetime is
  \begin{itemize}
  \item {\em globally hyperbolic, maximal, and Cauchy compact} (GHMC) whenever it is open and maximal under inclusion, that is, whenever it cannot be isometrically embedded into a strictly larger GHC anti-de Sitter spacetime;
  \item {\em globally hyperbolic, convex, and Cauchy compact} (GHCC) whenever it is compact, with boundary the disjoint union of two smooth, strongly convex, spacelike surfaces.

  \end{itemize}

\label{cr:landslides}
For all $\theta_-,\theta_+\in(0,\pi)$ and all $h_-,h_+\in\mathcal{T} $, the composition
\begin{equation*}
\mathcal S_{e^{i\theta_+},h_+}\circ\mathcal S_{e^{i\theta_-},h_-}:\mathcal{T} \longrightarrow\mathcal{T}\ .
\end{equation*}
has a unique fixed point.

The full translation $\tau$ intertwines $\widehat{\alpha}$ and $\alpha\times\alpha$, that is, for all $\mathbf{X},\mathbf{Y}\in\mathrm{SL}(2,\mathbb{R})$, and for all $(\mathbf{M},\mathbf{N})\in\mathrm{U}^+\mathrm{SL}(2,\mathbb{R})$,
\begin{equation}
\tau\big(\widehat{\alpha}(\mathbf{X},\mathbf{Y})\cdot(\mathbf{M},\mathbf{N})\big)
=\big(\alpha(\mathbf{X})\cdot\tau^r(\mathbf{M},\mathbf{N}),\alpha(\mathbf{Y})\cdot\tau^l(\mathbf{M},\mathbf{N})\big)\ .
\end{equation}

The function $\mathcal{N}$ intertwines $\alpha\times\alpha$ and $\widehat{\alpha}$, that is, for all $\mathbf{X},\mathbf{Y}\in\mathrm{SL}(2,\mathbb{R})$, and for all $([x],[y])\in\mathrm{P}\mathbb{R}^1\times\mathrm{P}\mathbb{R}^1$,
\begin{equation}
\mathcal{N}\big(\alpha(\mathbf{X})\cdot[x],\alpha(\mathbf{Y})\cdot[y]\big) = \widehat{\alpha}(\mathbf{X},\mathbf{Y})\cdot\mathcal{N}\big([x],[y]\big)\ .
\end{equation}

Indeed,
\begin{equation*}
\mathcal{N}\big(\alpha(\mathbf{X})\cdot[x],\alpha(\mathbf{Y})\cdot[y]\big)
=\mathcal{N}\big([\mathbf{X}\cdot x],[\mathbf{Y}\cdot y]\big) = [(\mathbf{X}\cdot x)\cdot(\mathbf{J}_0\cdot\mathbf{Y}\cdot y)^t]\ .
\end{equation*}
However, since $\mathrm{Det}(\mathbf{Y})=1$, by \eqref{eqn:DeterminantFormula},
\begin{equation*}
\mathbf{J}_0\cdot\mathbf{Y} = (\mathbf{Y}^{-1})^t\cdot\mathbf{J}_0\ .
\end{equation*}
Hence
\begin{align*}
\mathcal{N}\big(\alpha(\mathbf{X})\cdot[x],\alpha(\mathbf{Y})\cdot[y]\big)
&= [(\mathbf{X}\cdot x)\cdot((\mathbf{Y}^{-1})^t\cdot\mathbf{J}_0\cdot y)^t]\\
&= [(\mathbf{X}\cdot x)\cdot(y^t\cdot\mathbf{J}_0^t\cdot\mathbf{Y}^{-1})]\\
&= [\mathbf{X}\cdot(x\cdot(\mathbf{J}_0\cdot y)^t)\cdot\mathbf{Y}^{-1}]\\
&= [\mathbf{X}\cdot\widehat{\mathcal{N}}(x,y)\cdot\mathbf{Y}^{-1}]\\
&= \widehat{\alpha}(\mathbf{X},\mathbf{Y})\cdot\widehat{\mathcal{N}}(x,y)\ ,
\end{align*}
as desired.

Choose $\mathbf{M}\in G$ and denote $p:=\pi(\mathbf{M})$. For all $\gamma\in\Pi$,
\begin{equation*}
\begin{aligned}
\xi_{\mathbf{A}}\big(\rho(\gamma)\cdot p\big)
&=\frac{d}{dt}\pi\big(e^{t\mathbf{A}}\cdot\rho(\gamma)\cdot\mathbf{M}\big)\bigg|_{t=0}\\
&=\frac{d}{dt}\big(\big(e^{t\mathbf{A}}\cdot\rho(\gamma)\cdot e^{-t\mathbf{A}}\big)\cdot\big(e^{t\mathbf{A}}\cdot\mathbf{M}\big)\big)\bigg|_{t=0}\\
&=D\pi\big(\rho(\gamma)\cdot\mathbf{M}\big)\cdot\big([\mathbf{A}-\rho(\gamma)\cdot\mathbf{A}\cdot\rho(\gamma)^{-1}]\cdot\big(\rho(\gamma)\cdot\mathbf{M}\big)\big)\\
&\qquad\qquad +D\pi\big(\rho(\gamma)\cdot\mathbf{M}\big)\cdot\big(\rho(\gamma)\cdot\mathbf{A}\cdot\mathbf{M}\big)\vphantom{\frac{1}{2}}\ .
\end{aligned}
\end{equation*}
This first term is equal to $\xi_{\alpha_{\mathbf{A}}(\gamma)}(\rho(\gamma)\cdot p)$. For the second term, differentiating the identity $\pi\circ\rho(\gamma)=\rho(\gamma)\circ\pi$ yields
\begin{equation*}
D\pi\big(\rho(\gamma)\cdot\mathbf{M}\big)\circ D\rho(\gamma)(\mathbf{M}) = D\rho(\gamma)\big(\pi(\mathbf{M})\big)\circ D\pi(\mathbf{M})\ .
\end{equation*}
Hence
\begin{equation*}
\begin{aligned}
D\pi\big(\rho(\gamma)\cdot\mathbf{M}\big)\cdot\big(\rho(\gamma)\cdot\mathbf{A}\cdot\mathbf{M}\big)
&= D\pi\big(\rho(\gamma)\cdot\mathbf{M}\big)\cdot D\rho(\gamma)(\mathbf{M})\cdot(\mathbf{A}\cdot\mathbf{M})\\
&= D\rho(\gamma)\big(\pi(\mathbf{M})\big)\cdot D\pi(\mathbf{M})\cdot(\mathbf{A}\cdot\mathbf{M})\\
&= D\rho(\gamma)(p)\cdot\xi_{\mathbf{A}}(p)\ ,
\end{aligned}
\end{equation*}
and the result follows.

Upon applying an element of $\mathrm{P}\mathrm{SL}(2,\mathbb{R})$ if necessary, we may suppose that $p_3=\infty$. Since $\xi(\infty)=0$,
\begin{equation*}
\xi\in\mathfrak{h}=\mathrm{stab}(\infty)\ ,
\end{equation*}
so that
\begin{equation*}
\xi(x) = ax + b\ ,
\end{equation*}
for some $a,b\in\mathbb{R}$. Since $\xi(p_1)=\xi(p_2)=0$, it follows that $a=b=0$, and hence $\xi=0$, as desired.

Let $\rho:\Pi\rightarrow\mathrm{P}\mathrm{SL}(2,\mathbb{R})$ be Fuchsian, let $\alpha$ be a $\rho$-cocycle, and let $\xi$ be a $(\rho,\alpha)$-automorphic vector field. For all $\gamma\in\Pi\setminus\{\mathrm{Id}\}$, denoting by $p:=\rho(\gamma)^+$ the attractive fixed point of $\rho(\gamma)$ in $\mathrm{P}\mathbb{R}^1$,
\begin{equation}
\label{eqn:FormulaForAutomorphicVectorField}
\xi(p) = \frac{1}{\big(1-e^{-l_\rho(\gamma)}\big)}\xi_{\alpha(\gamma)}(p)\ ,
\end{equation}
where $l_\rho(\gamma)$ denotes the translation length of $\rho(\gamma)$.

Since $\rho$ is Fuchsian, $l_\rho(\gamma)>0$ for all non-trivial $\gamma$, and hence \eqref{eqn:FormulaForAutomorphicVectorField} is always finite. Upon conjugating with a suitable element of $\mathrm{P}\mathrm{SL}(2,\mathbb{R})$, we may suppose that the repulsive and attractive fixed points of $\rho(\gamma)$ are $\infty$ and $0$ respectively, and so
\begin{equation*}
\rho(\gamma)\cdot z = e^{-l_\rho(\gamma)}z\ .
\end{equation*}
Hence, for any $\xi$ tangent to $\mathrm{P}\mathbb{R}^1$ at $p=0$,
\begin{equation*}
D\rho(\gamma)(p)\cdot\xi = e^{-l_\rho(\gamma)}\xi\ .
\end{equation*}
Applying the cocycle condition \eqref{eqn:DefnCocycle} now yields
\begin{equation*}
\begin{aligned}
\xi(p) &= \xi\big(\rho(\gamma)\cdot p\big)\\
&= D\rho(\gamma)(p)\cdot\xi(p) + \xi_{\alpha(\gamma)}\big(\rho(\gamma)\cdot p)\big)\\
&= e^{-l_\rho(\gamma)}\cdot\xi(p) + \xi_{\alpha(\gamma)}(p)\ ,
\end{aligned}
\end{equation*}
and \eqref{eqn:FormulaForAutomorphicVectorField} follows.

Denote $\xi:=(\xi_r,\xi_l)$ and, for each $i$, denote $p_i:=(p_{i,r},p_{i,l})$. Since $\Lambda$ is the limit set of a quasi-Fuchsian representation, it is the graph of a homeomorphism $\phi:\mathrm{P}\mathbb{R}^1\rightarrow\mathrm{P}\mathbb{R}^1$. In particular, it projects bijectively onto each copy of $\mathrm{P}\mathbb{R}^1$. It follows that $(p_{1,r},p_{2,r},p_{3,r})$ and $(p_{1,l},p_{2,l},p_{3,l})$ are triples of distinct points in $\mathrm{P}\mathbb{R}^1$. For each $i$,
\begin{equation*}
\xi_r(p_{i,r}),\xi_l(p_{i,l})=0\ ,
\end{equation*}
so that, by Lemma \ref{lemma:VanishingConditionOfKillingFieldsI},
\begin{equation*}
\xi_r,\xi_l = 0\ ,
\end{equation*}
as desired.

We view $\mathrm{Ein}^{1,1}$ as the boundary of $\mathrm{AdS}^{2,1}$. Let $\zeta$ be a timelike geodesic in $\mathrm{AdS}^{2,1}$, let $\mathrm{Stab}(\zeta)$ denote its stabilizer in $\mathrm{P}\mathrm{SL}(2,\mathbb{R})\times\mathrm{P}\mathrm{SL}(2,\mathbb{R})$, and let $\mathrm{stab}(\zeta)$ denote the Lie algebra of this subgroup. Since $\mathrm{Stab}(\zeta)$ is isomorphic to $\mathbb{S}^1\times\mathbb{S}^1$, and acts transitively and without fixed points on $\mathrm{Ein}^{1,1}$, the function
\begin{equation*}
\phi:\mathrm{Ein}^{1,1}\times\mathrm{stab}(\zeta)\rightarrow\mathrm{T}\mathrm{Ein}^{1,1};(p,\mathbf{A})\mapsto\xi_{\mathbf{A}}(p)
\end{equation*}
is a bundle isomorphism. Let $\pi:\mathrm{Ein}^{1,1}\times\mathrm{stab}(\zeta)\rightarrow\mathrm{stab}(\zeta)$ denote the projection onto the fibre.

By Lemma \ref{lemma:ExistenceAndUniquenessOfAutomorphicFieldsII}, the composition $(\pi\circ\phi^{-1}\circ\xi)$ restricts to a function of Zygmund type over $\Lambda$. Since $\Lambda$ is rectifiable, the image $(\pi\circ\phi^{-1}\circ\xi)(\Lambda)$ has Hausdorff dimension $1$, and thus Lebesgue measure $0$. The set $(\Omega\cap\mathrm{stab}(\zeta))\setminus(\pi\circ\phi^{-1}\circ\xi)(\Lambda)$ is thus non-empty, and for any element $\mathbf{A}$ of this set, the vector field $\xi-\xi_{\mathbf{A}}$ is nowhere vanishing over $\Lambda$. The result follows.

By the rank-nullity theorem, it suffices to show that $\sigma$ is everywhere injective. However, if $\sigma\big((\mathbf{X},\mathbf{Y})_{\mathbf{M}}\big)=0$ for some $\mathbf{M}\in\mathrm{SL}(2,\mathbb{R})$ and $\mathbf{X},\mathbf{Y}\in\mathfrak{sl}(2,\mathbb{R})$, then
\begin{equation*}
\mathbf{X}^r(\mathbf{M}) = \mathbf{Y}^l(\mathbf{M}) = 0\ ,
\end{equation*}
so that, by invertibility of $\mathbf{M}$,
\begin{equation*}
\mathbf{X} = \mathbf{Y} = 0\ ,
\end{equation*}
as desired.

\label{lemma:LCCovariantDerivativeOfAdS}
For any vector field $\xi$ and for all $\mathbf{X}\in\mathfrak{sl}(2,\mathbb{R})$,
\begin{equation}
\label{eqn:LCCovariantDerivativeOfAdS}
\nabla_\xi\mathbf{X}^l = \xi\times\mathbf{X}^l\qquad\text{and}\qquad
\nabla_\xi\mathbf{X}^r = -\xi\times\mathbf{X}^r\ .
\end{equation}

Indeed (see, for example, \cite{milnor1976curvatures}), the Levi--Civita covariant derivatives of left and right invariant vector fields satisfy
\begin{equation*}
\nabla_{\mathbf{X}^l}\mathbf{Y}^l = \frac{1}{2}[\mathbf{X},\mathbf{Y}]^l\qquad\text{and}\qquad
\nabla_{\mathbf{X}^r}\mathbf{Y}^r = -\frac{1}{2}[\mathbf{X},\mathbf{Y}]^r\ ,
\end{equation*}
so that, by \eqref{eqn:CommutatorIsCrossProduct},
\begin{equation*}
\nabla_{\mathbf{X}^l}\mathbf{Y}^l = \mathbf{X}^l\times\mathbf{Y}^l\qquad\text{and}\qquad
\nabla_{\mathbf{X}^r}\mathbf{Y}^r = -\mathbf{X}^r\times\mathbf{Y}^r\ .
\end{equation*}
The result follows by tensoriality of the covariant derivative with respect to the first component.

\label{lemma:FormulaForConnectionForm}
For every vector field $\xi$, and for every section $(\mathbf{X},\mathbf{Y})$ of $E$,
\begin{equation}
\label{eqn:FormulaForConnectionFormI}
(\sigma^*\Omega)_\xi(\mathbf{X},\mathbf{Y}) = \big(-\tau^r(\xi)\times\mathbf{X},\tau^l(\xi)\times\mathbf{Y}\big)\ .
\end{equation}
Equivalently, for all vector fields $\xi$, $\eta_1$, and $\eta_2$,
\begin{equation}
\label{eqn:FormulaForConnectionFormII}
\Omega_\xi(\eta_1,\eta_2) = (-\xi\times\eta_2,-\xi\times\eta_1)\ .
\end{equation}

Indeed, choose $\mathbf{X},\mathbf{Y}\in\mathfrak{sl}(2,\mathbb{R})$, and identify the pair $(\mathbf{X},\mathbf{Y})$ with a constant section of $E$. In particular, for any $\xi$,
\begin{equation*}
D_\xi(\mathbf{X},\mathbf{Y}) = 0\ ,
\end{equation*}
so that
\begin{equation*}
(\sigma^*\Omega)_\xi(\mathbf{X},\mathbf{Y}) = (\sigma^*\nabla)_\xi(\mathbf{X},\mathbf{Y})\ .
\end{equation*}
By \eqref{eqn:LCCovariantDerivativeOfAdS}, for all $\xi$,
\begin{equation*}
\begin{aligned}
\nabla_\xi\sigma_*(\mathbf{X},\mathbf{Y})
&=\nabla_\xi\big(\mathbf{X}^r-\mathbf{Y}^l,\mathbf{X}^r+\mathbf{Y}^l\big)\\
&=\big(-\xi\times\mathbf{X}^r-\xi\times\mathbf{Y}^l,-\xi\times\mathbf{X}^r+\xi\times\mathbf{Y}^r\big)
\end{aligned}
\end{equation*}
Note now that, since the vector product is invariant under isometries of $\mathrm{SL}(2,\mathbb{R})$, for all $\mathbf{U},\mathbf{V}\in\mathfrak{sl}(2,\mathbb{R})$,
\begin{equation*}
(\mathbf{U}\times\mathbf{V})^r = \mathbf{U}^r\times\mathbf{V}^r\qquad\text{and}\qquad
(\mathbf{U}\times\mathbf{V})^l = \mathbf{U}^l\times\mathbf{V}^l\ .
\end{equation*}
Hence,
\begin{equation*}
\begin{aligned}
\nabla_\xi\sigma_*(\mathbf{X},\mathbf{Y})
&=\big(-(\tau^r(\xi)\times\mathbf{X})^r-(\tau^l(\xi)\times\mathbf{Y})^l,-(\tau^r(\xi)\times\mathbf{X})^r+(\tau^l(\xi)\times\mathbf{Y})^l\big)\\
&=\sigma_*\big(-\tau^r(\xi)\times\mathbf{X},\tau^l(\xi)\times\mathbf{Y}\big)\ ,
\end{aligned}
\end{equation*}
so that
\begin{equation*}
(\sigma^*\Omega)_\xi(\mathbf{X},\mathbf{Y}) = \big(-\tau^r(\xi)\times\mathbf{X},\tau^l(\xi)\times\mathbf{Y}\big)\ .
\end{equation*}
The first assertion follows, and the second assertion follows upon setting $\eta_1:=\mathbf{X}^r-\mathbf{Y}^l$ and $\eta_2:=\mathbf{X}^r+\mathbf{Y}^l$.

Since the spaces of Killing vector fields and of flat sections of $E$ are both $6$-dimen\-sional, it suffices to show that, for all $\mathbf{X},\mathbf{Y}\in\mathfrak{sl}(2,\mathbb{R})$,
\begin{equation*}
-\frac{1}{2}\nabla\times(\mathbf{X}^r-\mathbf{Y}^l) = \mathbf{X}^r + \mathbf{Y}^l\ .
\end{equation*}
To this end, let $(e_i)_{1\leq i\leq 3}$ be an orthonormal frame of $\mathrm{SL}(2,\mathbb{R})$. Note that, for each $i$, and for every tangent vector $\xi$,
\begin{equation*}
e_i\times(e_i\times\xi) = \langle e_i,e_i\rangle\pi_i(\xi)\ ,
\end{equation*}
where $\pi_i$ denotes the orthogonal projection onto $\langle e_i\rangle^\perp$. Thus, by \eqref{eqn:LCCovariantDerivativeOfAdS}, for all $\mathbf{X}\in\mathfrak{sl}(2,\mathbb{R})$,
\begin{equation*}
\begin{aligned}
\nabla\times\mathbf{X}^r
&=\sum_i\langle e_i,e_i\rangle e_i\times\big(\nabla_{e_i}\mathbf{X}^r\big)\\
&=\sum_i-\langle e_i,e_i\rangle e_i\times\big(e_i\times\mathbf{X}^r\big)\\
&=\sum_i-\langle e_i,e_i\rangle^2\pi_i\big(\mathbf{X}^r\big)\\
&=-2\mathbf{X}^r\ .
\end{aligned}
\end{equation*}
Likewise, for all $\mathbf{Y}\in\mathfrak{sl}(2,\mathbb{R})$,
\begin{equation*}
\nabla\times\mathbf{Y}^l = 2\mathbf{Y}^l\ .
\end{equation*}
Thus,
\begin{equation*}
\nabla\times\big(\mathbf{X}^r-\mathbf{Y}^l) = -2\big(\mathbf{X}^r + \mathbf{Y}^l\big)\ ,
\end{equation*}
and the result follows.

\label{lemma:GeometryOfTimelikeGeodesics}
Let $\zeta$ and $\widetilde{\zeta}$ be distinct timelike geodesics in $\mathrm{SL}(2,\mathbb{R})$.
\begin{itemize}
\item[(1)] Two points $\mathbf{M}\in\zeta$ and $\widetilde{\mathbf{M}}\in\widetilde{\zeta}$ are in spacelike relation if and only if
\begin{equation}
\left|\langle\mathbf{M},\pi_\zeta(\widetilde{\mathbf{M}})\rangle_{\mathrm{mat}}\right| > 1\ .
\end{equation}
Furthermore, when this holds, the spacelike distance between these points satisfies
\begin{equation}
\label{eqn:SpacelikeDistanceI}
\cosh\big(d(\mathbf{M},\widetilde{\mathbf{M}})\big) = \left|\langle\mathbf{M},\pi_\zeta(\widetilde{\mathbf{M}})\rangle_{\mathrm{mat}}\right|\ .
\end{equation}
\item[(2)] For all $\widetilde{\mathbf{M}}\in\widetilde{\zeta}$, the radial projection of $\pi_\zeta(\widetilde{\mathbf{M}})$ is, up to sign, the unique point of $\zeta$ maximizing spacelike distance to $\widetilde{\mathbf{M}}$. Furthermore, this distance satisfies
\begin{equation}
\label{eqn:SpacelikeDistanceII}
\cosh\big(d(\zeta,\widetilde{\mathbf{M}})\big) = \|\pi_\zeta(\widetilde{\mathbf{M}})\|_{\mathrm{mat}}\ .
\end{equation}
\item[(3)] If the spacelike distance $d_\zeta$ to $\zeta$ is non-constant over $\widetilde{\zeta}$, then there exists, up to sign, a unique point $\widetilde{\mathbf{M}}$ of $\widetilde{\zeta}$ maximizing spacelike distance to $\zeta$. Furthermore, $\pi_\zeta(\widetilde{\mathbf{M}})$ is an end-point of the major axis of $\pi_\zeta(\widetilde{\zeta})$.
\end{itemize}

To prove $(1)$, note that $\mathbf{M}$ and $\widetilde{\mathbf{M}}$ are in spacelike relation if and only if the plane they span has signature $(1,1)$. This in turn holds if and only if
\begin{equation*}
\left|\begin{matrix}\langle\mathbf{M},\mathbf{M}\rangle_{\mathrm{mat}}&\langle\mathbf{M},\widetilde{\mathbf{M}}\rangle_{\mathrm{mat}}\\
\langle\mathbf{M},\widetilde{\mathbf{M}}\rangle_{\mathrm{mat}}&\langle\widetilde{\mathbf{M}},\widetilde{\mathbf{M}}\rangle_{\mathrm{mat}}\end{matrix}\right| < 0\ .
\end{equation*}
Calculating this determinant, and bearing in mind that
\begin{equation*}
\|\mathbf{M}\|_{\mathrm{mat}}^2 = \|\widetilde{\mathbf{M}}\|_{\mathrm{mat}}^2 = -1\ ,
\end{equation*}
we find that this holds if and only if
\begin{equation*}
\left|\langle\mathbf{M},\pi_\zeta(\widetilde{\mathbf{M}})\rangle_{\mathrm{mat}}\right| = \left|\langle\mathbf{M},\widetilde{\mathbf{M}}\rangle_{\mathrm{mat}}\right| > 1\ ,
\end{equation*}
as asserted. In addition, when this holds, the spacelike geodesic in $\mathrm{AdS}^{2,1}$ from $\mathbf{M}$ to $\widetilde{\mathbf{M}}$ lies in the span of these two vectors, and \eqref{eqn:SpacelikeDistanceI} follows by classical hyperbolic geometry. This proves $(1)$.

By \eqref{eqn:SpacelikeDistanceI}, the spacelike distance to any fixed $\widetilde{\mathbf{M}}$ is maximized whenever the absolute value of the inner product
\begin{equation*}
\langle\mathbf{M},\widetilde{\mathbf{M}}\rangle_{\mathrm{mat}} = \langle\mathbf{M},\pi_\zeta(\widetilde{\mathbf{M}})\rangle_{\mathrm{mat}}
\end{equation*}
is maximized. This proves $(2)$. The final assertion follows upon maximizing \eqref{eqn:SpacelikeDistanceII}, and this completes the proof.

\label{lemma:ParametrizationOfSecondGeodesic}
With the above normalizations, up to reparametrization,
\begin{equation}
\label{eqn:ParametrizationOfSecondGeodesic}
\begin{aligned}
\widetilde{\zeta}(s) &= \cosh(\lambda-\mu)\cos(s)\sigma_0 + \cosh(\lambda+\mu)\sin(s)\sigma_1\\
&\qquad + \sinh(\lambda+\mu)\sin(s)\sigma_2 + \sinh(\lambda-\mu)\cos(s)\sigma_3\ .
\end{aligned}
\end{equation}
In particular
\begin{equation}
\label{eqn:ParametrizationOfSecondGeodesicII}
\pi_\zeta\big(\widetilde{\zeta}(s)\big) = \cosh(\lambda-\mu)\cos(s)\sigma_0 + \cosh(\lambda+\mu)\sin(s)\sigma_1\ .
\end{equation}
Furthermore, spacelike distance from $\zeta$ is maximized when $s=\pi/2$, where it is equal to $(\lambda+\mu)$.

Indeed, viewed as a set, $\widetilde{\zeta}$ consists of all $\mathbf{M}$ such that
\begin{equation*}
\mathbf{M}\cdot\tau^l(\widetilde{\zeta}) = \tau^r(\widetilde{\zeta})\cdot\mathbf{M}\ .
\end{equation*}
Define $\mathbf{M}_0$ and $\mathbf{N}_0$ by
\begin{equation*}
\begin{aligned}
\mathbf{M}_0 &:= \cosh(\lambda)\sigma_0 + \sinh(\lambda)\sigma_3\ \text{and}\\
\mathbf{N}_0 &:= \cosh(\mu)\sigma_0 + \sinh(\mu)\sigma_3\ .
\end{aligned}
\end{equation*}
By \eqref{eqn:BasicPauliRelationsI} and \eqref{eqn:BasicPauliRelationsII},
\begin{equation*}
\mathbf{M}_0\cdot\sigma_1\cdot\mathbf{M}_0^{-1} = \tau^r(\widetilde{\zeta})\qquad\text{and}\qquad\mathbf{N}_0\cdot\sigma_1\cdot\mathbf{N}_0^{-1} = \tau^l(\widetilde{\zeta})\ .
\end{equation*}
Hence, up to reparametrization
\begin{equation*}
\widetilde{\zeta}(s) = \mathbf{M}_0\cdot\zeta(s)\cdot\mathbf{N}_0^{-1}\ ,
\end{equation*}
where $\zeta$ is as in \eqref{eqn:ParametrizationOfFirstGeodesic}, and \eqref{eqn:ParametrizationOfSecondGeodesic} now follows by explicit calculation. Since the plane of $\zeta$ is $P:=\langle\sigma_0,\sigma_1\rangle$, \eqref{eqn:ParametrizationOfSecondGeodesicII} follows immediately. Finally, the minor and major axes of $\pi_\zeta(\widetilde{\zeta})$ are respectively $\sigma_0$ and $\sigma_1$, and it follows by Lemma \ref{lemma:GeometryOfTimelikeGeodesics}, Item $(3)$ that spacelike distance to $\zeta$ is maximized over $\widetilde{\zeta}$ at $s=\pi/2$, where it is equal to $(\lambda+\mu)$. This completes the proof.

\label{lemma:DistanceBetweenPointsOfTimelikeGeodesics}
For all $\epsilon>0$, there exists $C_1,C_2>0$ such that, if $\lambda,\mu>C_1$, and if $s,\widetilde{s}\in[\epsilon,\pi-\epsilon]$, then $\zeta_0(s)$ and $\widetilde{\zeta}(\widetilde{s})$ are in spacelike relation, and
\begin{equation}
\label{eqn:DistanceBetweenPointsOfTimelikeGeodesics}
d\big(\zeta(s),\widetilde{\zeta}(\widetilde{s})\big) \geq (\lambda+\mu) - C_2\ .
\end{equation}

Indeed, by \eqref{eqn:ParametrizationOfSecondGeodesicII}, for all $s,\widetilde{s}\in[0,\pi]$,
\begin{equation*}
\left|\langle\zeta(s),\widetilde{\zeta}(\widetilde{s})\rangle_{\mathrm{mat}}\right| = \cosh(\lambda-\mu)\cos(s)\cos(\widetilde{s}) + \cosh(\lambda+\mu)\sin(s)\sin(\widetilde{s})\ .
\end{equation*}
We minimize this quantity over $[\epsilon,\pi-\epsilon]^2$ by choosing $s$ and $\widetilde{s}$ such that the coefficient of $\cosh(\lambda+\mu)$ is as small as possible and the coefficient of $\cosh(\lambda-\mu)$ is negative and as large as possible. This happens when $s=\epsilon$ and $\widetilde{s}=\pi-\epsilon$. Hence, for all $s,s'\in[\epsilon,\pi-\epsilon]$,
\begin{equation*}
\left|\langle\zeta(s),\widetilde{\zeta}(\widetilde{s})\rangle_{\mathrm{mat}}\right| \geq \cosh(\lambda+\mu)\sin^2(\epsilon) - \cosh(\lambda-\mu)\cos^2(\epsilon)\ .
\end{equation*}
For $C_1$ sufficiently large, this quantity is greater than $1$ for all such $s$ and $\widetilde{s}$. Hence, by Lemma \ref{lemma:GeometryOfTimelikeGeodesics}, Item $(2)$, for $C_1$ sufficiently large, and for all such $s$ and $\widetilde{s}$, $\zeta(s)$ and $\widetilde{\zeta}(\widetilde{s})$ are in spacelike relation, and
\begin{equation*}
e^{d(\zeta(s),\widetilde{\zeta}(\widetilde{s}))} \geq\cosh\big(d(\zeta(s),\widetilde{\zeta}(\widetilde{s}))\big) \geq \frac{1}{2}\cosh(\lambda+\mu)\sin^2(\epsilon) \geq \frac{1}{4}e^{\lambda+\mu}\sin^2(\epsilon)\ .
\end{equation*}
The result follows upon taking logarithms.

\label{lemma:HLemma}
Let $\zeta$ and $\widetilde{\zeta}$ be future oriented timelike geodesics in $\mathrm{AdS}^{2,1}$ such that the spacelike distance between them is non-constant. Let $\eta$ denote the unique oriented spacelike geodesic in $\mathrm{AdS}^{2,1}$ joining their furthest points, and let $\eta^r$ (resp. $\eta^l$) denote the oriented geodesic in $\mathbb{H}^2$ from $\tau^r(\zeta)$ to $\tau^r(\widetilde{\zeta})$ (resp. from $\tau^l(\zeta)$ to $\tau^l(\widetilde{\zeta})$). The end-points of $\eta$ are related to those of $\eta^r$ and $\eta^l$ by
\begin{equation}
\label{eqn:HLemma}
\tau_\infty(\eta^\pm) = \big(\eta^{r,\pm},\eta^{l,\pm}\big)\ .
\end{equation}

Indeed, by Lemma \ref{lemma:ParametrizationOfSecondGeodesic}, with the above normalizations,
\begin{equation*}
\eta(t) = \eta^r(t) = \eta^l(t) = \cosh(t)\sigma_1 + \sinh(t)\sigma_2 = \mathbf{M}(t)\cdot\sigma_1\cdot\mathbf{M}(t)^{-1}\ ,
\end{equation*}
where, for all $t$,
\begin{equation*}
\mathbf{M}(t) := \cosh(t/2)\sigma_0 + \sinh(t/2)\sigma_3\ .
\end{equation*}
Denote $\mathbf{M}_1:=\mathbf{M}(1)$. Let $\widehat{\alpha}\big(\mathbf{M}_1,\mathbf{M}_1\big)^\pm$ denote the attractive and repulsive fixed points of $\widehat{\alpha}\big(\mathbf{M}_1,\mathbf{M}_1\big)$ in $\mathrm{Ein}^{1,1}$, and let $\alpha\big(\mathbf{M}_1\big)^\pm$ denote the attractive and repulsive fixed points of $\alpha\big(\mathbf{M}_1\big)$ in $\partial_\infty\mathbf{H}^2$. Bearing in mind \eqref{eqn:defn:EquivarianceOfLimitI},
\begin{equation*}
\tau_\infty(\eta^{\pm}) = \tau_\infty\big(\widehat{\alpha}\big(\mathbf{M}_1,\mathbf{M}_1\big)^\pm\big) = \big(\alpha\big(\mathbf{M}_1\big)^\pm,\alpha\big(\mathbf{M}_1\big)^\pm\big) = \big(\eta^{r,\pm},\eta^{l,\pm}\big)\ ,
\end{equation*}
as desired.

\label{lemma:EstimateOfTranslationField}
For all $\epsilon>0$, there exists $C>0$ such that, for all $s\in[\epsilon,\pi-\epsilon]$,
\begin{equation}
\label{eqn:EstimateOfTranslationField}
-\|X_\zeta(\widetilde{\zeta}(s))\|^2_{\mathrm{mat}} \geq C_2\cosh^2(\lambda+\mu)\ .
\end{equation}

Indeed, since $\sigma_0$ and $\sigma_1$ are orthonormal and timelike, by \eqref{eqn:RestrictionOfTranslationToGeodesic},
\begin{equation*}
-\|X_\zeta(\widetilde{\zeta}(s))\|_{\mathrm{mat}}^2 = \cosh^2(\lambda-\mu)\cos^2(s) + \cosh^2(\lambda+\mu)\sin^2(s)\geq \cosh^2(\lambda+\mu)\sin^2(\epsilon)\ .
\end{equation*}
The result follows upon setting $C:=\sin^2(\epsilon)$.

\label{lemma:TangentComponentOfTranslationField}
For all $s\in[0,\pi]$,
\begin{equation}
\label{eqn:TangentComponentOfTranslationField}
\langle X_\zeta(\widetilde{\zeta}(s)),\partial_s\widetilde{\zeta}(s)\rangle_{\mathrm{mat}} = -2\cosh(\lambda+\mu)\cosh(\lambda-\mu)\ .
\end{equation}

Indeed, differentiating \eqref{eqn:ParametrizationOfSecondGeodesicII} yields, for all $s$,
\begin{equation*}
\partial_s\pi_\zeta\big(\widetilde\zeta(s)\big) = -\cosh(\lambda-\mu)\sin(s)\sigma_0 + \cosh(\lambda+\mu)\cos(s)\sigma_1\ .
\end{equation*}
The result follows upon taking the inner product with \eqref{eqn:RestrictionOfTranslationToGeodesic}.

For all $\epsilon>0$, there exists $C>0$ such that, for all $s\in[\epsilon,\pi-\epsilon]$,
\begin{equation}
\label{eqn:NormOfRestrictionOfRotationVectorField}
\|Y_\zeta(\widetilde{\zeta}(s))\|^2_{\mathrm{mat}} \geq C_2\sinh^2(\lambda+\mu)\ .
\end{equation}

Indeed, since $\sigma_2$ and $\sigma_3$ are orthonormal and spacelike, by \eqref{eqn:RotationVectorFieldOverGeodesic},
\begin{equation*}
\|Y_\zeta(\widetilde{\zeta}(s))\|^2_{\mathrm{mat}} = \sinh^2(\lambda-\mu)\cos^2(s) + \sinh^2(\lambda+\mu)\sin^2(s) \geq \frac{1}{2}\sin^2(\epsilon)\sinh^2(\lambda+\mu)\ .
\end{equation*}
The result follows upon setting $C_2:=\sin^2(\epsilon)$.

For all $s\in[0,\pi]$,
\begin{equation*}
\langle Y_\zeta(\widetilde{\zeta}(s)),\partial_s\widetilde{\zeta}(s)\rangle = -\sinh(\lambda+\mu)\sinh(\lambda-\mu)\ .
\end{equation*}

Indeed, differentiating \eqref{eqn:ParametrizationOfSecondGeodesic} yields, for all $s$,
\begin{equation*}
\begin{aligned}
\partial_s\widetilde{\zeta}(s) &= -\cosh(\lambda-\mu)\sin(s)\sigma_2 + \cosh(\lambda+\mu)\cos(s)\sigma_1\\
&\qquad +\sinh(\lambda+\mu)\cos(s)\sigma_2 - \sinh(\lambda-\mu)\sin(s)\sigma_3\ .
\end{aligned}
\end{equation*}
The result follows upon taking the inner product with \eqref{eqn:RotationVectorFieldOverGeodesic}.

Let $\rho,\widetilde{\rho}:\Pi\rightarrow\mathrm{P}\mathrm{SL}(2,\mathbb{R})$ be Fuchsian representations. Then
\begin{equation}
\label{eqn:thurstonlipschitz}
\sup_{\gamma\in\Pi\setminus\{e\}}\left|\ln\big(l_\rho(\gamma)\big) - \ln\big(l_{\widetilde{\rho}}(\gamma)\big)\right| \leq d_{\mathrm{Lip}}(\rho,\widetilde{\rho})\ .
\end{equation}

Indeed, denote $d:=d_{\mathrm{Lip}}(\rho,\widetilde{\rho})$ and $D:=e^d$. Denote $S:=\mathbb{H}^2/\rho(\Pi)$ and $\widetilde{S}:=\mathbb{H}^2/\widetilde{\rho}(\Pi)$. For all non-trivial $\gamma\in\Pi$, let $c(\gamma)$ (resp. $\widetilde{c}(\gamma)$) denote the unique closed geodesic freely homotopic to $\rho(\gamma)$ (resp. $\widetilde{\rho}(\gamma)$) in $S$ (resp. $\widetilde{S}$). Let $\widehat{\phi}:\mathbb{H}^2\rightarrow\mathbb{H}^2$ be a $(\rho,\widetilde{\rho})$-equivariant $D$-bilipschitz map, and let $\phi$ denote its projection to $S$. For all non-trivial $\gamma\in\Pi$,
\begin{equation*}
l_\rho(\gamma) = \mathrm{Length}\big(c(\gamma)\big) \geq \frac{1}{D}\mathrm{Length}\big((\phi\circ c)(\gamma)\big)\ .
\end{equation*}
Since $\widetilde{c}(\gamma)$ minimizes length in the free homotopy class of $\widetilde{\rho}(\gamma)$, it follows that
\begin{equation*}
l_\rho(\gamma) \geq \frac{1}{D}\mathrm{Length}\big(\widetilde c(\gamma)\big) = \frac{1}{D} l_{\widetilde \rho}(\gamma)\ .
\end{equation*}
Taking logarithms yields
\begin{equation*}
\ln\big(l_{\widetilde{\rho}}(\gamma)\big) - \ln\big(l_{\rho}(\gamma)\big) \leq \ln(D) = d\ .
\end{equation*}
Likewise, by symmetry,
\begin{equation*}
\ln\big(l_\rho(\gamma)\big) - \ln\big(l_{\widetilde{\rho}}(\gamma)\big) \leq \ln(D) = d\ .
\end{equation*}
The result follows upon combining these estimates.

\label{lemma:HowKappaIsReallyUsed}
Let $\rho,\widetilde{\rho}:\Pi\rightarrow\mathrm{P}\mathrm{SL}(2,\mathbb{R})$ be Fuchsian representations, and let $d:=d_{\mathrm{Lip}}(\rho,\rho')$ denote the Lipschitz distance between the two. For every point $p\in\mathbb{H}^2$,
\begin{equation}
\label{eqn:HowKappaIsReallyUsed}
\limsup_{\left|\gamma\right|\rightarrow\infty}\frac{\left|l_{\rho,p}(\gamma)-l_{\widetilde{\rho},p}(\gamma)\right|}{l_{\rho,p}(\gamma)+l_{\widetilde{\rho},p}(\gamma)} \leq \tanh(d/2)\ ,
\end{equation}
where $|\gamma|$ here denotes the word length of $\gamma$ for an arbitrary finite set of generators of $\Pi$.

Denote $d:=d_{\mathrm{Lip}}(\rho,\widetilde{\rho})$ and denote $D:=e^d$. Let $\phi:\mathbb{H}^2\rightarrow\mathbb{H}^2$ be a $(\rho,\widetilde{\rho})$-equivariant $D$-bilipschitz map. For all non-trivial $\gamma\in\Pi$,
\begin{equation*}
\begin{aligned}
l_{\widetilde{\rho},p}(\gamma) &= d\big(\widetilde{\rho}(\gamma)\cdot p,p\big)\\
&\leq d\big(\widetilde{\rho}(\gamma)\cdot p,\widetilde{\rho}(\gamma)\cdot\phi(p)\big) + d\big(\widetilde{\rho}(\gamma)\cdot\phi(p),\phi(p)\big) + d\big(\phi(p),p\big)\\
&\leq 2d\big(\phi(p),p\big) + d\big(\phi(\rho(\gamma)\cdot p),\phi(p)\big)\\
&\leq 2d\big(\phi(p),p\big) + D\cdot d\big(\rho(\gamma)\cdot p,p\big)\\
&\leq C + D\cdot l_{\rho,p}(\gamma)\ ,
\end{aligned}
\end{equation*}
for some $C$ independent of $\gamma$. By symmetry,
\begin{equation*}
l_{\rho,p}(\gamma) \leq C + D\cdot l_{\widetilde{\rho},p}(\gamma)\ .
\end{equation*}
Hence,
\begin{equation*}
\frac{1}{D} \leq \liminf_{\left|\gamma\right|\rightarrow\infty}\frac{l_{\widetilde{\rho},p}(\gamma)}{l_{\rho,p}(\gamma)}
\leq \limsup_{\left|\gamma\right|\rightarrow\infty}\frac{l_{\widetilde{\rho},p}(\gamma)}{l_{\rho,p}(\gamma)}
\leq D\ .
\end{equation*}

Consider now the M\"obius map
\begin{equation*}
M(x) := \frac{1-x}{1+x}\ .
\end{equation*}
This map sends the interval $[1/D,D]$ to the interval $[-\tanh(d/2),\tanh(d/2)]$. Thus, since
\begin{equation*}
\frac{\left|l_{\rho,p}(\gamma)-l_{\widetilde{\rho},p}(\gamma)\right|}{l_{\rho,p}(\gamma)+l_{\widetilde{\rho},p}(\gamma)}
=\left|M\bigg(\frac{l_{\widetilde{\rho},p}(\gamma)}{l_{\rho,p}(\gamma)}\bigg)\right| ,
\end{equation*}
the result follows.

\label{lemma:BoundsOfRadialComponentI}
There exists a compact subset $K\subseteq\Sigma$, and $C>0$ such that, for all $p\in\Sigma\setminus K$,
\begin{equation}
\label{eqn:BoundsOfRadialComponentI}
\frac{1}{C} \leq -\langle N(p),e_r(p)\rangle \leq C\ .
\end{equation}

For all $p\in\Sigma$, let $\pi_p^{\mathrm{pa}}(\Lambda)\subseteq\mathrm{U}_p\mathrm{AdS}^{2,1}$ denote the radial projection of $\Lambda$ into the space of unit, spacelike tangent vectors at $p$. Since every such point lies in the invisibility domain of $\Lambda$, this is always a compact set of unit, spacelike vectors over $p$.

Let $\Sigma_0$ be a fundamental domain of $\Sigma$. For $p\in\Sigma_0$ and $q\in\Lambda$, let $\eta$ denote the unit speed spacelike geodesic from $p$ to $q$ such that $\eta(0)=p$. Its derivative $\xi:=\partial\eta(0)$ is an element of $\pi_p^{\mathrm{pa}}(\Lambda)$, and every element of $\pi_p^{\mathrm{pa}}(\Lambda)$ arises in this manner. By strict convexity, $\xi$ is strictly inward-pointing, so that
\begin{equation*}
\langle N(p),\xi\rangle > 0\ .
\end{equation*}
On the other hand, trivially,
\begin{equation*}
\langle N(p),\xi\rangle < \infty\ .
\end{equation*}
It follows by compactness of $\Lambda$ and $\Sigma_0$ that there exists $C>0$ such that, for all $p\in\Sigma_0$, and for all $\xi\in\pi_p^{\mathrm{pa}}(\Lambda)$,
\begin{equation}
\label{eqn:proof:BoundsOfRadialComponentI}
\frac{2}{C} < \langle N(p),\xi\rangle < \frac{C}{2}\ .
\end{equation}

We now conclude using $\rho$-invariance. Let $(p_m)_{m\in\mathbb{N}}$ be a diverging sequence of points of $\Sigma$. For all $m$, let $\gamma_m\in\Pi$ be such that $\widetilde{p}_m:=\rho(\gamma_m)\cdot p_m$ is an element of $\Sigma_0$. Suppose furthermore that $(\widetilde{p}_m)_{m\in\mathbb{N}}$ converges to some limit point $\widetilde{p}_\infty$, say. For all $m$, denote $q_m:=\rho(\gamma_m)\cdot p_0$ and $\xi_m:=-D\rho(\gamma_m)(p_m)\cdot e_r(p_m)$. Since $(q_m)_{m\in\mathbb{N}}$ diverges, we may suppose that it converges to some point $q_\infty$, say, of $\Lambda$. It then follows that $(\xi_m)_{m\in\mathbb{N}}$ converges to some point $\xi_\infty$, say, of $\pi_{\widetilde{p}_\infty}^{\mathrm{pa}}(\Lambda)$. Consequently,
\begin{equation*}
\begin{aligned}
\lim_{m\rightarrow\infty}\langle N(p_m),e_r(p_m)\rangle
&=\lim_{m\rightarrow\infty}\langle D\rho(\gamma_m)(p_m)\cdot N(p_m),D\rho(\gamma_m)(p_m)\cdot e_r(p_m)\rangle\\
&=\lim_{m\rightarrow\infty}-\langle N(\widetilde{p}_m),\xi_m\rangle\\
&=-\langle N(\widetilde{p}_\infty),\xi_\infty\rangle\ ,
\end{aligned}
\end{equation*}
and the result now follows by \eqref{eqn:proof:BoundsOfRadialComponentI}.

For any $\rho$-invariant vector field $X$ over $M$, there exists a compact subset $K\subseteq M$ and $C>0$ such that, for all $p\in M\setminus K$,
\begin{equation*}
\left|\langle X(p),e_r(p)\rangle\right| < C\ .
\end{equation*}

\label{lemma:GrowthRateOfTilt}
For every $\rho$-invariant, unit timelike vector field $\xi$ over $M$ and for all $k>\kappa_\rho$, there exists a compact subset $K$ of $M$ and $C\geq 0$ such that, for all $p\in M\setminus K$,
\begin{equation}
\label{eqn:GrowthRateOfTilt}
\angle_a\big(\xi(p),f_t(p)\big) \leq k\cdot d(p_0,p) + C\ .
\end{equation}

\label{lemma:ProjectionOntoGeodesicOfLambda}
There exists $\epsilon>0$ such that, for all $p\in\Sigma$,
\begin{equation*}
\pi_p^{\mathrm{cyl}}(\Lambda)\subseteq[-\pi/2+\epsilon,-\epsilon]\ .
\end{equation*}

Note that the problem is $\rho$-invariant. Let $\Sigma_0$ be a fundamental domain of $\Sigma$ and choose $p\in\Sigma_0$. Choose a Kleinian chart such that $p=(1,0,0)^t$ and $\zeta_p$ is the upward-pointing $x_0$-axis. In this chart, the outward-pointing Minkowski unit normal to $\Sigma$ at $p$ is $N:=(1,0,0)^t$. Let $\Sigma^*$ denote the dual convex surface of $\Sigma$, and observe that $\Sigma^*$ contains the point $(-1,0,0)^t$ with outward-pointing Minkowski normal $(-1,0,0)^t$ at this point. Thus, if $\widetilde{M}$ denotes the convex set bounded by $\Sigma$ and $\Sigma^*$, then $\widetilde{M}$ is contained in the slab
\begin{equation*}
S:=\{(x_0,x_1,x_2)\ |\ -1\leq x_0\leq 1\}\ .
\end{equation*}
Since $\Sigma$ and $\Sigma^*$ are strongly convex, and since $\Lambda\subseteq\partial_\infty\widetilde{M}$, it follows that $\Lambda$ is contained in the slightly narrower slab
\begin{equation*}
S':=\{(x_0,x_1,x_2)\ |\ -1+\epsilon_1\leq x_0\leq 1-\epsilon_1\}\ ,
\end{equation*}
for some $\epsilon_1>0$, which can be chosen uniformly for all $p \in \Sigma_0$. The orthogonal projection of $\Lambda$ onto the $x_0$-axis is thus contained in the interval $[-1+\epsilon_1,1-\epsilon_1]$, and the preimage under $\zeta_p$ of this interval is contained in $[-\pi/2+\epsilon,-\epsilon]$, for some $\epsilon>0$, which may likewise be chosen uniformly for all $p \in \Sigma_0$. The result now follows by $\rho$-invariance.

\label{lemma:GrowthRateOfTiltStepI}
For all $k>\kappa_\rho$, there exists a compact subset $K$ of $\Sigma$ and $C>0$ such that, for all $p\in\Sigma\setminus K$, and for all $s,\widetilde{s}\in[-\pi/2,0]$,
\begin{equation*}
\label{eqn:GrowthRateOfTiltStepI}
\angle_a\big(\partial_s\zeta_p(s),f_t(\zeta_p(s))\big) \leq k\cdot d\big(\zeta_0(\widetilde{s}),\zeta_p(s)\big) + C\ .
\end{equation*}

Let $\Sigma_0$ be a fundamental domain of $\Sigma$ and suppose that $\zeta_0$ passes through $\Sigma_0$. Let $\tau$ denote the full translation map defined in Section \ref{sss:AntideSitterSpaceInMatrixModel} and denote $(q_r,q_l):=\tau(\zeta_0)$. Without loss of generality, we may suppose that there exists $\gamma\in\Pi$ such that $\zeta_p = \rho(\gamma)\circ\zeta_0$. As in Section \ref{ss:TimelikeGeodesicsInTheMatrixModel}, denote
\begin{equation*}
\lambda:=\frac{1}{2}d\big(q_r,\tau_r(\zeta_p)\big)\qquad\text{and}\qquad\mu:=\frac{1}{2}d\big(q_l,\tau_l(\zeta_p)\big)\ ,
\end{equation*}
and note that both $\lambda$ and $\mu$ are non-zero.

By Lemma \ref{lemma:LocationOfFurthestPoint}, the furthest point $s_0$ of $\zeta_p$ from $\zeta_0$ is an element of $[-\pi/2+\epsilon,-\epsilon]$, so that
\begin{equation}
\label{lemma:GrowthRateOfTiltStepI:I}
\left|s-s_0\right|\leq\frac{\pi}{2}-\epsilon\ .
\end{equation}
Similarly, if $\widetilde{s}_0$ denotes the furthest point of $\zeta_0$ from $\zeta_p$, then
\begin{equation}
\label{lemma:GrowthRateOfTiltStepI:II}
\left|\widetilde{s}-\widetilde{s}_0\right|\leq\frac{\pi}{2}-\epsilon\ .
\end{equation}

By \eqref{lemma:GrowthRateOfTiltStepI:I}, since $f_t$ is the unit vector field in the direction of $X_{\zeta_0}$, \eqref{eqn:EstimateOfTranslationField} and \eqref{eqn:TangentComponentOfTranslationField} yield
\begin{equation*}
\left|\langle \partial_s\zeta_p(s),f_t(\zeta_p(s))\rangle\right| \leq \frac{1}{C_1}\cosh(\lambda-\mu)\ .
\end{equation*}
However, by \eqref{eqn:HowKappaIsReallyUsed}, for $q$ outside a sufficiently large compact set,
\begin{equation*}
\cosh(\lambda-\mu) \leq \cosh\big(k\cdot(\lambda+\mu)\big)\ ,
\end{equation*}
so that
\begin{equation*}
\left|\langle \partial_s\zeta_p(s),f_t(\zeta_p(s))\rangle\right| \leq \frac{1}{C_2}\cosh\big(k\cdot(\lambda+\mu)\big)\ .
\end{equation*}
Taking logarithms yields
\begin{equation*}
\angle_a\big(\partial_s\zeta_p(s),f_t(\zeta_p(s))\big) \leq k\cdot(\lambda+\mu) + C_3\ .
\end{equation*}

By \eqref{lemma:GrowthRateOfTiltStepI:II}, \eqref{eqn:DistanceBetweenPointsOfTimelikeGeodesics} yields
\begin{equation*}
\angle_a\big(\partial_s\zeta_p(s),f_t(\zeta_p(s))\big) \leq k\cdot d\big(\zeta_0(\widetilde{s}),\zeta_p(s)\big) + C_3\ ,
\end{equation*}
and the result follows.

Let $\mathrm{Conv}(\Lambda)$ denote the convex hull of $\Lambda$ in $\mathrm{AdS}^{2,1}$. Since $\mathrm{Conv}(\Lambda)$ is the intersection of all convex sets containing $\Lambda$, in particular,
\begin{equation*}
\mathrm{Conv}(\Lambda) \subseteq \widetilde{M}_1,\widetilde{M}_2,M\ .
\end{equation*}
Note that $M\setminus\mathrm{Conv}(\Lambda)$ consists of two connected components, one corresponding to each boundary component of $M$. Since $\widetilde{M}_1$ contains $\Sigma_1$ and $\mathrm{Conv}(\Lambda)$, by convexity, it contains the entire connected component of $M\setminus\mathrm{Conv}(\Lambda)$ containing $\Sigma_1$. Similarly, $\widetilde{M}_2$ contains the entire connected component of $M\setminus\mathrm{Conv}(\Lambda)$ containing $\Sigma_2$. It follows that $M\subseteq\widetilde{M}_1\cup\widetilde{M}_2$, as desired.

Choose $q\in M$. Without loss of generality, we may assume that $q\in\widetilde{M}_1$. Let $p\in\Sigma$ denote the point in $\Sigma$ maximizing timelike distance to $q$ and note that $q=\zeta_p(s)$ for some $s\in [-\pi/2, 0]$. By $\rho$-invariance and cocompactness,
\begin{equation*}
\angle_a\big(\xi(p),\partial_s\zeta_p(s)\big) \leq C\ ,
\end{equation*}
for some $C$ that is independent of $p$. The result follows by \eqref{eqn:GrowthRateOfTiltStepI} and the triangle inequality.

\label{lemma:FramesApproachExponentially}
There exists a compact subset $K$ of $M$ and $C>0$ such that, for all $\mathbf{y}\in M\setminus K$,
\begin{equation}
\label{eqn:FramesApproachExponentiallyI}
\angle_a\big(f_t^a(\mathbf{y}),e_t^a(\mathbf{y})\big)\leq Ce^{-r_a(\mathbf{y})}\ ,
\end{equation}
where $r_a(\mathbf{y})$ denotes the anti-de Sitter distance to $p_0$, as defined in \eqref{eqn:AntiDeSitterDistance}. In particular,
\begin{equation}
\label{eqn:FramesApproachExponentiallyII}
\lim_{r_a\rightarrow+\infty}\angle_a(f_t^a,e_t^a) = 0\ .
\end{equation}

Indeed, let $C>0$ be such that $\Lambda$ is contained in the slab
\begin{equation*}
S := \big\{ (y_0,y_1,y_2)^t\ |\ \left|y_0\right| \leq C \big\}\ .
\end{equation*}
Consider now the point $\mathbf{y}:=(y_0,y_1,y_2)=\Phi(r,\theta,t)$. Without loss of generality, we may suppose that $\theta=0$, so that $y_2=0$. Differentiating $\Phi$ in the $r$-direction yields
\begin{equation*}
\partial_r = \frac{1}{r}(y_0,y_1,0)^t\ .
\end{equation*}
Hence, by \eqref{eqn:defn:AntiDeSitterOrthonormalFrame},
\begin{equation*}
e_r^a = \frac{(1-r^2)}{r}(y_0,y_1,0)^t\ .
\end{equation*}

Consider now the curve $\gamma(s) := (y_0,s,0)^t$. Trivially,
\begin{equation*}
\partial_s\gamma(s) = (0,1,0)^t\ .
\end{equation*}
In order to determine $f^a_r$, we determine the anti de Sitter length of this vector as follows. First, the preimage of $\gamma$ in $\mathbb{R}^{2,2}$ is
\begin{equation*}
\widehat{\gamma}(s) = \frac{1}{\sqrt{1+y_0^2-s^2}}(1,y_0,s,0)^t\ .
\end{equation*}
Differentiating yields
\begin{equation*}
\partial_s\widehat{\gamma}(s) = \frac{s}{\sqrt{1+y_0^2-s^2}^3}(1,y_0,0,0)^t + \frac{(1+y_0^2)}{\sqrt{1+y_0^2-s^2}^3}(0,0,1,0)^t\ .
\end{equation*}
Hence
\begin{equation*}
\|\partial_s\gamma\|_a^2 = \|\partial_s\widehat{\gamma}\|^2 = \frac{(1+y_0^2)}{(1+y_0^2-s^2)^2}\ .
\end{equation*}
Thus, noting that $r^2=s^2-y_0^2$,
\begin{equation*}
f^a_r = \frac{(1-r^2)}{\sqrt{1+y_0^2}}(0,1,0)^t\ .
\end{equation*}

We now have
\begin{equation*}
\cosh\big(\angle_a(e_t^a,f_t^a)\big) = \cosh\big(\angle_a(e_r^a,f_r^a)\big) = \left|\langle e_r^a,f_r^a\rangle\right| = \frac{y_1}{r\sqrt{1+y_0^2}}\ .
\end{equation*}
Hence
\begin{equation*}
\sinh\big(\angle_a(e_t^a,f_t^a)\big) = \frac{y_0}{\sqrt{1-r^2}}{r(1+y_0^2)} = \frac{y_0}{r(1+y_0^2)\cosh\big(r_a(\mathbf{y})\big)}\ ,
\end{equation*}
and the result follows.

\label{lemma:GrowthRateOfTAngle}
For every $\rho$-invariant field $X$ of anti-de Sitter unit, future oriented timelike vectors over $M$, and for all $k>\kappa_\rho$, there exists a compact subset $K$ of $M$, and $C>0$ such that, for all $\mathbf{y}\in M\setminus K$,
\begin{equation}
\label{eqn:GrowthRateOfTAngle}
\angle_a\big(e_t^a(\mathbf{y}),X(\mathbf{y})\big) \leq k\cdot r_a(\mathbf{y}) + C\ .
\end{equation}

Indeed, by Lemma \ref{lemma:GrowthRateOfTilt}, there exists $C>0$ such that, for all $\mathbf{y}$,
\begin{equation*}
\angle_a\big(f_t^a(\mathbf{y}),X(\mathbf{y})\big) \leq k\cdot r_a(\mathbf{y}) + C\ .
\end{equation*}
The result now follows by \eqref{eqn:FramesApproachExponentiallyI} and the triangle inequality.

\label{lemma:EstimatesOfOmega}
For all $k>\kappa_\rho$, there exists a compact subset $K$ of $M$, and $C>0$ such that, for all $\mathbf{y}\in M\setminus K$, for each $i$, and for $\eta_1,\eta_2\in\{e_t^m,e_\theta^m\}$,
\begin{equation}
\label{eqn:defn:EstimatesOfOmega}
\begin{aligned}
\left|\langle\omega_i^\xi(e_r^m),e_r^m\rangle_e\right| &\leq C\ ,\\
\left|\langle\omega_i^\xi(\eta_1),e_r^m\rangle_e\right| &\leq C\delta(\mathbf{y})^{(1-k)/2}\ ,\\
\left|\langle\omega_i^\xi(e_r^m),\eta_1\rangle_e\right| &\leq C\delta(\mathbf{y})^{-(1+k)/2}\ ,\ \text{and}\\
\left|\langle\omega_i^\xi(\eta_1),\eta_2\rangle_e\right| &\leq C\delta(\mathbf{y})^{-k}\ .
\end{aligned}
\end{equation}

Let $X$ be a $\rho$-invariant field of timelike directions over $M$. Let $M_0$ be a fundamental domain of $M$. Let $\mathrm{U}^{\mathrm{sp}}\mathrm{AdS}^{2,1}$ denote the bundle of unit spacelike tangent vectors over $\mathrm{AdS}^{2,1}$. For $\mathbf{y}\in M$, let $\pi_{\mathbf{y}}^{\mathrm{sp}}(\Lambda)$ denote the radial projection of $\Lambda$ onto the fibre $\mathrm{U}^{\mathrm{sp}}_{\mathbf{y}}\mathrm{AdS}^{2,1}$, and note that
\begin{equation*}
\Omega_0:=\bigcup_{\mathbf{y}\in M_0}\pi_{\mathbf{y}}^{\mathrm{sp}}(\Lambda)
\end{equation*}
is a compact subset of $\mathrm{U}^{\mathrm{sp}}\mathrm{AdS}^{2,1}$. Let $\Omega$ be a relatively compact neighbourhood of $\Omega_0$ in $\mathrm{U}^{\mathrm{sp}}\mathrm{AdS}^{2,1}$. For all $\mathbf{y}\in M_0$, let $\Omega_{\mathbf{y}}$ denote the fibre of $\Omega_0$ over $\mathbf{y}$, and extend this by $\rho$-invariance to a family $(\Omega_{\mathbf{y}})_{\mathbf{y}\in M}$ over the whole of $M$. For $\mathbf{y}\in M$, and for $\nu\in\Omega_{\mathbf{y}}$, we define the orthonormal frame $F^{\mathbf{y},\nu}:=\big(f_1^{\mathbf{y},\nu},f_2^{\mathbf{y},\nu},f_3^{\mathbf{y},\nu}\big)$ such that $f_1^{\mathbf{y},\nu}=\nu$, $f_2^{\mathbf{y},\nu}$ lies in the orthogonal projection of ${X}$ onto $\langle\nu\rangle^\perp$, and $f_3^{\mathbf{y},\nu}=f_1^{\mathbf{y},\nu}\times^a f_2^{\mathbf{y},\nu}$. Note that
\begin{equation*}
(F^{\mathbf{y},\nu})_{\mathbf{y}\in M_0,\nu\in\overline{\Omega}_\mathbf{y}}
\end{equation*}
is a compact subset of the orthonormal frame bundle of $\mathrm{AdS}^{2,1}$.

By compactness, there exists $C>0$ such that, for all $\mathbf{y}\in M_0$, $\nu\in\Omega_{\mathbf{y}}$, and for all $i$, $j$, $k$,
\begin{equation}
\label{eqn:proof:EstimatesOfOmegaI}
\left|\langle\omega_i^\xi(f_i^{\mathbf{y},\nu}),f_j^{\mathbf{y},\nu}\rangle_a\right| \leq C\ .
\end{equation}
By $\rho$-invariance, \eqref{eqn:proof:EstimatesOfOmegaI} holds for all $\mathbf{y}\in M$.

Choose $\mathbf{y}\in M$ and set $\nu:=e_r^a$. We estimate the distance between the frames $F^{\mathbf{y},\nu}$ and $(e_r^a,e_t^a,e_\theta^a)$. Indeed, by definition,
\begin{equation*}
f_1^{\mathbf{y},\nu} = e_r^a\ .
\end{equation*}
Now, since $e_t^a$ is orthogonal to $e_r^a$,
\begin{equation*}
\angle_a(f_2^{\mathbf{y},\nu},e_t^a) \leq \angle_a(X(\mathbf{y}),e_t^a)\ .
\end{equation*}
Hence, by \eqref{eqn:GrowthRateOfTAngle}, there exists a compact set $K$ and $C_1>0$ such that, over $M\setminus K$,
\begin{equation*}
\angle_a\big(f_2^{\mathbf{y},\nu},e_t^a\big) \leq k\cdot r_a(\mathbf{y}) + C_1\ .
\end{equation*}
Finally,
\begin{equation*}
\angle_a\big(f_3^{\mathbf{y},\nu},e_\theta^a\big)=\angle_a\big(f_2^{\mathbf{y},\nu},e_t^a\big) \leq k\cdot r_a(\mathbf{y}) + C_1\ .
\end{equation*}
This suffices for our purposes to describe the relationship between these two frames.

By the above estimates, for each $i$, and for all $\eta_1^a,\eta_2^a\in\{e_t^a,e_\theta^a\}$,
\begin{equation*}
\begin{aligned}
\left|\langle\omega_i^\xi(e_r^a),e_r^a\rangle_a\right| &\leq& &C_2\ , & &\\
\left|\langle\omega_i^\xi(\eta_1),e_r^a\rangle_a\right| &\leq& &C_2 e^{k\cdot r_a(\mathbf{y})} &\leq &\ C_3 \delta(\mathbf{y})^{-k/2}\ ,\\
\left|\langle\omega_i^\xi(e_r^a),\eta_1\rangle_a\right| &\leq& &C_2 e^{k\cdot r_a(\mathbf{y})} &\leq &\ C_3 \delta(\mathbf{y})^{-k/2}\ ,\ \text{and}\\
\left|\langle\omega_i^\xi(\eta_1),\eta_2\rangle_a\right| &\leq& &C_2 e^{2k\cdot r_a(\mathbf{y})} &\leq &\ C_3 \delta(\mathbf{y})^{-k}\ .
\end{aligned}
\end{equation*}Hence, for each $i$, and for all $\eta_1^m,\eta_2^m\in\{e_t^m,e_\theta^m\}$,
\begin{equation*}
\begin{aligned}
\left|\langle\omega_i^\xi(e_r^m),e_r^m\rangle_m\right| &\leq C_4\ ,\\
\left|\langle\omega_i^\xi(\eta_1),e_r^m\rangle_m\right| &\leq C_4 \delta(\mathbf{y})^{(1-k)/2}\ ,\\
\left|\langle\omega_i^\xi(e_r^m),\eta_1\rangle_m\right| &\leq C_4 \delta(\mathbf{y})^{-(1+k)/2}\ ,\ \text{and}\\
\left|\langle\omega_i^\xi(\eta_1),\eta_2\rangle_m\right| &\leq C_4 \delta(\mathbf{y})^{-k}\ .
\end{aligned}
\end{equation*}
The result now follows upon observing that the Wick rotation of the Minkowski metric about $e_t^m$ is uniformly equivalent to the Euclidian metric.

\label{lemma:ExplicitAffineConnectionForm}
\begin{equation*}
\label{eqn:ExplicitAffineConnectionForm}
\alpha = \frac{r}{(1-r^2)}dr\ .
\end{equation*}

By symmetry, $\alpha=\phi dr$ for some $\phi$. Next observe that, for any unit, spacelike vector $\mathbf{y}$,
\begin{equation*}
\gamma := \tanh(t)\mathbf{y}
\end{equation*}
is a unit speed $\mathrm{AdS}^{2,1}$ geodesic. Denote $r:=\tanh(t)$ and differentiating yields
\begin{equation*}
\partial_t\gamma = \frac{1}{\cosh^2(t)}\partial_r = (1-r^2)\partial_r\ .
\end{equation*}
Hence
\begin{equation*}
\nabla^a_{\partial_r}\partial_r = \nabla^a_{\partial_r}(1-r^2)^{-1}\partial_t\gamma = \frac{2r}{(1-r^2)^2}\partial_t\gamma = \frac{2r}{(1-r^2)}\partial_r\ ,
\end{equation*}
so that
\begin{equation*}
2\alpha(\partial_r)\partial_r = \nabla^a_{\partial_r}\partial_r - \nabla_{\partial_r}\partial_r = \frac{2r}{(1-r^2)}\partial_r\ ,
\end{equation*}
and the result follows.

\label{lemma:CovariantDerivativeOfXi}
For all $X$,
\begin{equation}
\label{eqn:CovariantDerivativeOfXi}
\begin{aligned}
\nabla_X\xi &= \omega_1^\xi(X) + X\times^a\eta - \alpha(X)\xi - \alpha(\xi)X\ ,\ \text{and}\\
\nabla_X\eta &= \omega_2^\xi(X) + X\times^a\xi - \alpha(X)\eta - \alpha(\eta)X\ .
\end{aligned}
\end{equation}

Indeed, by \eqref{eqn:FormulaForConnectionFormII},
\begin{equation*}
\nabla_X^a(\xi,\eta) = D_x(\xi,\eta) + (X\times^a\eta,X\times^a\xi)\ .
\end{equation*}
Thus, bearing in mind \eqref{eqn:AffineConnectionForm},
\begin{equation*}
\begin{aligned}
\nabla_X\xi
&= \nabla_X^a\xi - \alpha(X)\xi - \alpha(\xi)X\\
&= D_X\xi + X\times^a\eta - \alpha(X)\xi - \alpha(\xi)X\\
&= \omega_1^\xi(X) + X\times^a \eta - \alpha(X)\xi - \alpha(\xi)X\ ,
\end{aligned}
\end{equation*}
and the first identity follows. The second identity is proven in a similar manner, and this completes the proof.

\label{lemma:EstimateOfRadialComponent}
There exists $C>0$ such that
\begin{equation}
\label{eqn:EstimateOfRadialComponent}
\|\xi^r\|_e,\|\eta^r\|_e \leq C\delta(\mathbf{y})\big(1+\left|\ln\big(\delta(\mathbf{y})\big)\right|\big)\ .
\end{equation}

Indeed, bearing in mind \eqref{eqn:CovariantDerivativeOfXi},
\begin{equation*}
\begin{aligned}
\partial_r\xi^r &= \langle\nabla_{\partial_r}\xi,\partial_r\rangle_m\\
&=\langle\omega_1^\xi(\partial_r),\partial_r\rangle_m - 2\alpha(\partial_r)\langle\xi,\partial_r\rangle_m\\
&=\langle\omega_1^\xi(\partial_r),\partial_r\rangle_m - \frac{2r}{(1-r^2)}\xi^r\ .
\end{aligned}
\end{equation*}
Thus, bearing in mind \eqref{eqn:defn:EstimatesOfOmega},
\begin{equation*}
\left|\partial_r\bigg(\frac{1}{(1-r^2)}\xi^r\bigg)\right| = \frac{1}{(1-r^2)}\left|\langle\omega_1^\xi(\partial_r),\partial_r\rangle_m\right| \leq \frac{C}{(1-r^2)}\ .
\end{equation*}
Integrating over radial lines yields
\begin{equation*}
\frac{1}{(1-r^2)}\left|\xi^r\right| \leq C\big(1+\left|\ln(1-r)\right|\big)\ ,
\end{equation*}
so that
\begin{equation*}
\left|\xi^r\right| \leq C\delta\big(1+\left|\ln(\delta)\right|\big)\ ,
\end{equation*}
as desired. The estimate for $\eta^r$ is addressed in a similar manner, and this completes the proof.

\label{lemma:UniformConvergence}
For all $k>\kappa_\rho$, there exists $C>0$ such that, if $\mathbf{y}$ and $\mathbf{y}'$ are colinear radial vectors, then
\begin{equation*}
\|\xi^{\mathrm{pa}}(\mathbf{y}) - \xi^{\mathrm{pa}}(\mathbf{y}')\|_e \leq C\max\big(\delta(\mathbf{y})^{\frac{(1-k)}{2}},\delta(\mathbf{y}')^{\frac{(1-k)}{2}}\big)\ .
\end{equation*}

Let $\pi$ denote the orthogonal projection along $\partial_r$, and observe that
\begin{equation*}
\nabla_{\partial_r}\pi = 0\ .
\end{equation*}
In particular,
\begin{equation*}
\nabla_{\partial_r}\xi^{\mathrm{pa}} = \nabla_{\partial_r}\pi(\xi) = \pi\big(\nabla_{\partial_r}\xi\big)\ ,
\end{equation*}
and
\begin{equation*}
\nabla_{\partial_r}\eta^{\mathrm{pa}} = \nabla_{\partial_r}\pi(\eta) = \pi\big(\nabla_{\partial_r}\eta\big)\ .
\end{equation*}
Thus, by \eqref{eqn:CovariantDerivativeOfXi},
\begin{equation*}
\nabla_{\partial_r}\xi^{\mathrm{pa}} = \omega_1^\xi(\partial_r)^{\mathrm{pa}} + \partial_r\times^a\eta - \alpha(\partial_r)\xi\ ,
\end{equation*}
and
\begin{equation*}
\nabla_{\partial_r}\eta^{\mathrm{pa}} = \omega_2^\xi(\partial_r)^{\mathrm{pa}} + \partial_r\times^a\xi - \alpha(\partial_r)\eta\ .
\end{equation*}
Note now that, by \eqref{eqn:defn:MinkowskiOrthonormalFrame} and \eqref{eqn:defn:AntiDeSitterOrthonormalFrame},
\begin{equation*}
\partial_r\times^a = e_r^m\times^a = \frac{1}{(1-r^2)}e_r^a\times^a = \frac{1}{(1-r^2)}e_r^m\times^m\ ,
\end{equation*}
so that
\begin{equation}
\label{eqn:DerivativeOfXiEta}
\begin{aligned}
\nabla_{\partial_r}\big(\xi^{\mathrm{pa}},\eta^{\mathrm{pa}})
&=\big(\omega_1^\xi(\partial_r)^{\mathrm{pa}},\omega_2^\xi(\partial_r)^{\mathrm{pa}}\big)\\
&\qquad\qquad + \frac{1}{(1-r^2)}\big(e_r^m\times^m\eta^{\mathrm{pa}},e_r^m\times^m\xi^{\mathrm{pa}}\big)
 - \frac{r}{(1-r^2)}\big(\xi^{\mathrm{pa}},\eta^{\mathrm{pa}}\big)\ .
\end{aligned}
\end{equation}

Consider now the vector field $\nu := \xi^{\mathrm{pa}} - e_r^m\times^m\eta^{\mathrm{pa}}$. The preceding identity yields
\begin{equation*}
\nabla_{\partial_r}\nu = \big(\omega_1^\xi(\partial_r)^{\mathrm{pa}} - e_r^m\times^m\omega_2^\xi(\partial_r)^{\mathrm{pa}}\big) - \frac{1}{(1-r)}\nu\ .
\end{equation*}
Hence
\begin{equation*}
\nabla_{\partial_r}\frac{1}{(1-r)}\nu = \frac{1}{(1-r)}\big(\omega_1^\xi(\partial_r)^{\mathrm{pa}} - e_r^m\times^m\omega_2^\xi(\partial_r)^{\mathrm{pa}}\big)\ ,
\end{equation*}
so that, by \eqref{eqn:defn:EstimatesOfOmega},
\begin{equation*}
\big\|\nabla_{\partial_r}\frac{1}{(1-r)}\nu\big\|_e \leq C_1(1-r)^{-\frac{(3+k)}{2}}\ .
\end{equation*}
Integrating over the radial line passing through $\mathbf{y}$ and $\mathbf{y}'$ yields
\begin{equation*}
\|\frac{1}{(1-r)}\nu\| \leq C_1\big(1 + (1-r)^{-\frac{(1+k)}{2}}\big)\ ,
\end{equation*}
so that
\begin{equation*}
\label{eqn:EstimateForNu}
\|\nu\| \leq C_1(1-r)^{\frac{(1-k)}{2}}\ .
\end{equation*}

Substiting $\nu$ into the first component of \eqref{eqn:DerivativeOfXiEta} now yields
\begin{equation*}
\nabla_{\partial_r}\xi^{\mathrm{pa}} = \omega_1^\xi(\partial_r)^{\mathrm{pa}} - \frac{1}{(1-r^2)}\nu + \frac{1}{(1+r)}\xi^{\mathrm{pa}}\ ,
\end{equation*}
so that, by \eqref{eqn:defn:EstimatesOfOmega} again
\begin{equation*}
\big\|\nabla_{\partial_r}\frac{1}{(1+r)}\xi^{\mathrm{pa}}\big\|_e \leq C_2 (1-r)^{-\frac{(1-k)}{2}}\ ,
\end{equation*}
and the result follows upon integrating this identity along the radial segment joining $\mathbf{y}$ and $\mathbf{y}'$.

It suffices to prove that $P_1\xi$ extends smoothly over the light cone. By rotational symmetry about the $y_0$ axis, it also suffices to address the analogous result over $\mathrm{AdS}^{1,1}$. Let $\partial_r$ and $\partial_t$ denote respectively the radial and pseudoangular vector fields of pseudospherical coordinates in $\Omega^s$. By \eqref{eqn:defn:PseudoSphericalCoordinates},
\begin{equation*}
\partial_r = \frac{y_0}{r}\partial_{y_0} + \frac{y_1}{r}\partial_{y_1}\qquad\text{and}\qquad
\partial_t = y_1\partial_{y_0} + y_0\partial_{y_1}\ .
\end{equation*}
In terms of the basis $(\partial_{y_0},\partial_{y_1})$, the first Pogorelov transform is given at every point $(y_0,y_1)$ of $\Omega^s$ by the matrix
\begin{equation*}
P_1 = \frac{-1}{r}
\begin{pmatrix}y_0/r\hfill& y_1\hfill\\ y_1/r\hfill& y_0\hfill\end{pmatrix}
\cdot\begin{pmatrix}1/(1-r^2)\hfill& 0\hfill\\ 0\hfill& 1\hfill\end{pmatrix}
\cdot\begin{pmatrix}y_0\hfill& -y_1\hfill\\ -y_1/r\hfill& y_0/r\hfill\end{pmatrix}\ .
\end{equation*}
Since $r^2=y_1^2-y_0^2$,
\begin{equation*}
P_1 = \frac{1}{1+y_0^2-y_1^2}\begin{pmatrix}1-y_1^2\hfill& y_0y_1\hfill\\ -y_0y_1\hfill& 1+ y_0^2\hfill\end{pmatrix}\ .
\end{equation*}
We likewise obtain the same formula over $\Omega^t$, and smoothness of $P_1\xi$ follows.

We use the notation of \cite[Section V.2]{Vek}, and it will thus be preferable to denote the variation vector field provisionally by $X=:(\xi,\eta,\zeta)$. Upon rotating if necessary, we may suppose that, near $p$, $\Sigma$ is the graph of a function $z(x,y)$. We define the tangent frame $(e_x,e_y)$ near $p$ by
\begin{equation*}
e_x:=\partial_x + z_x\partial_z\qquad\text{and}\qquad e_y:=\partial_y+z_y\partial_z\ ,
\end{equation*}
and we denote by $(f_x,f_y)$ its dual frame with respect to the Euclidian metric. If $\pi(X)$ denotes the Euclidian orthogonal projection onto $T\Sigma$, then
\begin{equation*}
\pi(X) = u\cdot f_x + v\cdot f_y\ ,
\end{equation*}
where
\begin{equation*}
u := \xi + z_x\zeta\qquad\text{and}\qquad v:=\eta+z_y\zeta\ .
\end{equation*}
By $(2.9)$ of \cite[Section V.2]{Vek}, the function $w:=u+iv$ satisfies an equation of Beltrami type. By \cite[Theorem $3.30$]{Vek}, there therefore exists a quasiconformal local homeomorphism $W$ and a smooth holomorphic function $f$, such that, near $p$,
\begin{equation*}
w(x+iy) = f\big(W(x+iy)\big)\ ,
\end{equation*}
and the result follows.

\label{lemma:AsymptoticsOfNormal}
For all $k>\kappa_\rho$, over $\Omega$,
\begin{equation*}
\label{eqn:AsymptoticsOfNormal}
N^m = \big(1 + \mathrm{O}(\delta)\big)e^m_r + \mathrm{O}\big(\delta^{\frac{1-k}{2}}\big) e^m_\theta + \mathrm{O}\big(\delta^{\frac{1-k}{2}}\big) e^m_t\ ,
\end{equation*}
where $\delta$ is as in \eqref{eqn:DefinitioOfDelta}. In particular $N^m$ extends continuously to $\Lambda$.

Indeed, let $N^a$ denote the anti de Sitter unit normal vector field over $\partial M$. For $p\in\Sigma\cap\Omega$, denote
\begin{equation*}
N^a(p) = \alpha e^a_r + \beta e^a_\theta + \gamma e^a_t\ ,
\end{equation*}
and note that
\begin{equation*}
\label{eqn:EstimateOfNormalProofI}
\alpha^2 + \beta^2 - \gamma^2  = -1\ .
\end{equation*}
By \eqref{eqn:BoundsOfRadialComponentI}, we may suppose that there exists $C>0$ such that
\begin{equation}
\label{eqn:EstimateOfNormalProofII}
\frac{1}{C} \leq \alpha \leq C\ .
\end{equation}
By \eqref{eqn:GrowthRateOfTAngle}, we may suppose furthermore that
\begin{equation}
\label{eqn:EstimateOfNormalProofIII}
\left|\gamma\right| \leq C\delta^{-\frac{k}{2}}\ ,
\end{equation}
and hence, by \eqref{eqn:EstimateOfNormalProofI}
\begin{equation}
\label{eqn:EstimateOfNormalProofIV}
\left|\beta\right| \leq C\delta^{-\frac{k}{2}}\ .
\end{equation}

Define $\widehat{N}^m$ by
\begin{equation*}
\widehat{N}^m := \frac{\alpha}{\delta} e^m_r + \frac{\beta}{\sqrt{\delta}}e^m_\theta + \frac{\gamma}{\sqrt{\delta}}e^m_t\ .
\end{equation*}
By \eqref{eqn:defn:MinkowskiOrthonormalFrame} and \eqref{eqn:defn:AntiDeSitterOrthonormalFrame}, $\widehat{N}_m$ is a (non-unit) Minkowski normal of $\partial M$ at $p$. Using \eqref{eqn:EstimateOfNormalProofI}, we find that its Minkowski norm-squared satisfies
\begin{equation*}
\|\widehat{N}^m\|_m^2 = \frac{\alpha^2}{\delta^2} + \frac{\beta^2}{\delta} - \frac{\gamma^2}{\delta} = \frac{\alpha^2}{\delta^2} - \frac{(\alpha^2+1)}{\delta}\ .
\end{equation*}
In particular, by \eqref{eqn:EstimateOfNormalProofII}, we may suppose that $\widehat{N}^m$ is spacelike and that its length $\lambda$ satisfies
\begin{equation*}
\lambda = \frac{\alpha}{\delta}\cdot\big(1 + \mathrm{O}(\delta)\big)\ .
\end{equation*}
The unit Minkowski normal of $\partial M$ at $p$ is thus
\begin{equation*}
N^m = \frac{1}{\lambda}\widehat{N}^m = \big(1+\mathrm{O}(\delta)\big)\cdot e^m_r + \mathrm{O}\big(\delta^{\frac{1}{2}}\big)\cdot\beta\cdot e^m_\theta + \mathrm{O}\big(\delta^{\frac{1}{2}}\big)\cdot\gamma\cdot e^m_t\ ,
\end{equation*}
and the result now follows by \eqref{eqn:EstimateOfNormalProofIII} and \eqref{eqn:EstimateOfNormalProofIV}.

By rotational symmetry about the $y_0$-axis, it suffices to consider the restriction to the $(y_0,y_1)$-plane. Denote
\begin{equation*}
Y' := \big\{ (y_0,y_1)\ \big|\ y_1^2-y_0^2 = 1\big\}\ .
\end{equation*}
This curve is parametrized by
\begin{equation*}
\mathbf{y}(t) := \big(\sinh(t),\cosh(t)\big)\ .
\end{equation*}
The tangent vector of this parametrization at $t$ is
\begin{equation*}
T(t) := \big(\cosh(t),\sinh(t)\big)\ ,
\end{equation*}
and, trivially,
\begin{equation*}
P_2T(t) = \big(-\cosh(t),\sinh(t)\big)\ .
\end{equation*}
Hence,
\begin{equation*}
(\pi^e\circ P_2)\big(T(t)\big) = \frac{1}{\|T(t)\|_e^2}\langle T(t),P_2T(t)\rangle_e\cdot T(t) = \frac{T(t)}{\cosh(2t)}\neq 0\ .
\end{equation*}
It follows that $(\pi^e\circ P_2)$ restricts to a bundle isomorphism over $T\partial\Omega$, as desired.

We first show that $\widetilde{\xi}:=\pi^e(P_2P_1\xi)$ extends continuously to $\Lambda$. Indeed, over $\Omega$, we denote respectively by $\xi^r$ and $\xi^{\mathrm{pa}}$ the radial and pseudoangular components of $\xi$. By Lemma \ref{lemma:ContinuousExtension}, $\xi$ extends continuously to $\Lambda$, and its restriction to this set is an automorphic vector field tangent to $\mathrm{Ein}^{1,1}$. By Lemma \ref{eqn:EstimateOfRadialComponent}, $\xi^{\mathrm{pa}}$ also extends continuously to $\Lambda$, and its restriction to this set coincides with that of $\xi$ and hence is also an automorphic vector field tangent to $\mathrm{Ein}^{1,1}$.

By Lemma \ref{lemma:EstimateOfRadialComponent}, and by definition of the first Pogorolov transform $P_1$, there exists $C_1>0$ such that, near $\Lambda$,
\begin{equation*}
\|P_1\xi^r\|_e \leq C_1\big(1+\left|\ln(\delta(\mathbf{y}))\right|\big)\ .
\end{equation*}
Note now that, for any Minkowski timelike immersed surface, the second Pogorelov transform of its Minkowski normal is colinear with its Euclidean normal. Thus, by \eqref{eqn:AsymptoticsOfNormal}, for all $k>\kappa_\rho$, there exists $C_2>0$ such that, near $\Lambda$,
\begin{equation*}
\|\pi^e(P_2P_1\xi^r)\|_e \leq C_2\delta(\mathbf{y})^{\frac{1-k}{2}}\cdot\big(1+\left|\ln(\delta(\mathbf{y}))\right|\big)\ .
\end{equation*}
Since this converges to $0$ near $\Lambda$, the vector field
\begin{equation*}
\widetilde{\xi} = \pi^e\big(P_2P_1\xi^r\big) + \pi^e\big(P_2P_1\xi^{\mathrm{pa}}\big)
\end{equation*}
extends continuously to $\Lambda$, and its restriction to this set coincides with that of $\pi^e(P_2P_1\xi^{\mathrm{pa}})$.

Now let $\Sigma$ and $\Sigma'$ denote the two boundary components of $M$. We claim that, over $\Sigma$, $\xi$ is the restriction of some Killing vector field of $\mathrm{AdS}^{2,1}$. Indeed, suppose the contrary. We will first show that, upon adding a Killing vector field to $\xi$ if necessary, we may suppose that $\widetilde{\xi}$ vanishes at at least $3$ distinct points of $\Sigma$. Indeed, let $E$ denote the $6$-dimensional space of Killing vector fields of $\mathrm{AdS}^{2,1}$. For all $p\in\partial \overline{M}$, define $\Phi_p:E\rightarrow T_p\partial\overline{M}$ by
\begin{equation*}
\Phi_p(\eta) := \pi^e\big(P_2P_1\eta(p)\big)\ .
\end{equation*}
By Lemmas \ref{lemma:VanishingConditionOfKillingFieldsII} and \ref{lemma:BundleIsomorphism}, for any $3$ distinct points $p_1,p_2,p_3\in\Lambda$, the linear map $\Phi:=\big(\Phi_{p_1},\Phi_{p_2},\Phi_{p_3}\big)$ has trivial kernel, and is therefore a linear isomorphism. Since $T\partial\overline{M}$ is continuous, we may perturb $(p_1,p_2,p_3)$ to $3$ distinct points of $\Sigma$. Upon replacing $\xi$ with $\xi-\eta$ if necessary, for some Killing vector field $\eta$, we may suppose that $\widetilde{\xi}$ vanishes at $p_1$, $p_2$ and $p_3$, as desired.

We now show that these zeroes are stable under small perturbations. To this end, we show that $\widetilde{\xi}$ does not vanish identically over $\Sigma$. Note first that, if $\widetilde{\xi}$ vanishes identically over $\Sigma$, then so too does $P_2P_1\xi$. Indeed, for any first order isometric variation field $\mu$, with tangential component $\mu^{\mathrm{t}}$ and normal component $\mu^{\mathrm{n}}$,
\begin{equation*}
2\langle\mu^{\mathrm{n}},N\rangle\mathrm{II} = -\mathcal{L}_{\mu^{\mathrm{t}}}g\ ,
\end{equation*}
where $N$, $\mathrm{II}$, and $g$ denote respectively the unit normal vector field, the second fundamental form, and the induced metric. Since $\Sigma$ is locally strongly convex, $\mathrm{II}$ is nowhere vanishing, and it follows that $\mu^{\mathrm{n}}$, and therefore also $\mu$, vanishes whenever $\mu^{\mathrm{t}}$ does. Finally, since $\xi$ is not the restriction of an anti-de Sitter Killing vector field, $P_2P_1\xi$ is not the restriction of a Euclidean Killing vector field, and, in particular, does not vanish identically over $\Sigma$. It follows that $\widetilde{\xi}$ does not vanish identically over $\Sigma$ either. Thus, by Lemma \ref{lemma:LocalGuageEquivalence}, the zeroes of $\widetilde{\xi}$ over $\Sigma$ are stable under small perturbations, as desired.

By Lemma \ref{lemma:NowhereVanishingProperty}, upon perturbing by a Killing field if necessary, we may suppose that the continuous extension of $P_1\xi^{\mathrm{pa}}$ is \emph{nowhere vanishing} over $\Lambda$. By Lemma \ref{lemma:BundleIsomorphism}, we may suppose that the same holds for the continuous extension of $\pi^e(P_2P_1\xi^{\mathrm{pa}})$, and therefore also for $\widetilde{\xi}$. By the preceding discussion, upon making this perturbation sufficiently small, we may still suppose that $\widetilde{\xi}$ vanishes at $3$ distinct points close to $p_1$, $p_2$, and $p_3$.

By Lemma \ref{lemma:LocalGuageEquivalence}, the set of zeroes of $\widetilde{\xi}$ over $\Sigma$ is discrete and every zero has positive, integer winding number. Since $\widetilde{\xi}$ does not vanish over $\Lambda$, it does not vanish identically over $\Sigma'$ and, by Lemma \ref{lemma:LocalGuageEquivalence}, again, the set of zeros of $\widetilde{\xi}$ over $\Sigma'$ is also discrete, and every zero has positive, integer winding number. Since $\mathrm{T}\partial\overline{M}$ is homeomorphic to $\mathrm{T}\mathbb{S}^2$, it has total degree $2$, and $\widetilde{\xi}$ therefore has at most $2$ distinct zeroes over $\Sigma\cup\Sigma'$. This is absurd, and it follows that over $\Sigma$, $\xi$ is the restriction of some Killing vector field $\eta$, say, of $\mathrm{AdS}^{2,1}$, as asserted.

By the same argument, over $\Sigma'$, $\xi$ is the restriction of some Killing vector field $\eta'$, say, of $\mathrm{AdS}^{2,1}$. Since $\eta$ and $\eta'$ coincide over $\Lambda$, they are equal. The vector field $\xi$ is thus the restriction to $\partial M$ of a Killing vector field of $\mathrm{AdS}^{2,1}$, and this completes the proof.

\label{thm:ExistenceAndUniquenessForLabourieFields}
Choose $\sigma_1,\sigma_2\in\widehat{\mathcal{T}}$, for each $i\in\{1,2\}$, let $\phi_i$ be a $\sigma_i$-invariant smooth function such that $\phi_i>1$, and let $u_i$ denote the unique smooth, $\sigma_i$-invariant function such that $\kappa[u_i]=-\phi_i$. There exists a unique pair $(A_1,A_2)$ such that, for each $i$, $A_i$ is a $\sigma_i$-invariant $(\phi_i-1)$-Labourie field, and
\begin{equation}
\label{eqn:EqualityOfRepresentations}
\rho^+[u_1,A_1] = \rho^-[u_2,A_2]\ .
\end{equation}

\label{lemma:ContinuityMethodOpenness}
Suppose that, for each $i$, there exists a $\sigma_i$-invariant $(\phi_{i,0}-1)$-Labourie field $A_i$ of $g[u_{i,0}]$ such that
\begin{equation*}
\rho^+[u_1,A_1] = \rho^-[u_2,A_2]\ .
\end{equation*}
Upon reducing $\epsilon$ if necessary, there exists a unique pair of continuous families $(A_{1,t})_{t\in]-\epsilon,\epsilon[}$ and $(A_{2,t})_{t\in]-\epsilon,\epsilon[}$ such that
\begin{enumerate}
\item $A_{1,0}=A_1$ and $A_{2,0}=A_2$;
\item for each $i$, $A_{i,t}$ is a $\sigma_i$-invariant $(\phi_{i,t}-1)$-Labourie field of $g[u_{i,t}]$; and
\item for all $t$, $\rho^+[u_{1,t},A_{1,t}]=\rho^-[u_{2,t},A_{2,t}]$.
\end{enumerate}

For each $i$, let $\mathcal{L}_i$ denote the space of $\sigma_i$-invariant $(\phi_{i,0}-1)$-Labourie fields of $g[u_{i,0}]$ and recall that this is a smooth, real $(6g-6)$-dimensional manifold. Define $F_1:\mathcal{L}_1\rightarrow\mathcal{T}\times\mathcal{T}$ and $F_2:\mathcal{L}_2\rightarrow\mathcal{T}\times\mathcal{T}$ by
\begin{equation*}
F_1(A) := \rho^+[u_{1,0},A]\qquad\text{and}\qquad F_2(A) := \rho^-[u_{2,0},A]\ ,
\end{equation*}
and note that $F_1$ and $F_2$ are trivially smooth.

We claim that $(F_1,F_2)$ is transverse to the diagonal of $(\mathcal{T}\times\mathcal{T})^2$ at $(A_{1,0},A_{2,0})$. Indeed, for each $i$, let $B_i$ be a tangent vector of $\mathcal{L}_i$ at $A_{i,0}$, and suppose that
\begin{equation*}
\xi:=\big(DF_1(A_{1,0})\cdot B_1,DF_2(A_{2,0})\cdot B_2\big)
\end{equation*}
is tangent to the diagonal of $(\mathcal{T}\times\mathcal{T})^2$. It suffices to show that $B_1=B_2=0$. To this end, let $M$ denote the convex subset of $\mathrm{AdS}^{2,1}$ bounded by $e^+[u_{1,0},A_{1,0}]$ and $e^-[u_{2,0},A_{2,0}]$. The vector $\xi$ yields a first order isometric variation of $\partial M$ which we also denote by $\xi$. By Theorem \ref{thm:InfinitesimalRigidity}, $\xi$ is the restriction of some Killing vector field over $\mathrm{AdS}^{2,1}$. Since Killing vector fields yield trivial first order variations of the shape operator, it follows that $B_1=B_2=0$, as asserted. Transversality now follows upon counting dimensions, and the result follows upon applying the implicit function theorem.

For each $i$, for all $m$, and for all $\gamma\in\Pi$, let $l_{i,m}(\gamma)$ denote the length of the unique curve in the free homotopy class of $\sigma_i(\gamma)$ which is a geodesic with respect to the metric $g[u_{i,m}]$. For all $m$, let $\Lambda_m$ denote the limit set of $\rho_m$ in $\mathrm{Ein}^{1,1}$, let $K_m$ denote its convex hull, and let $\partial K_m^+$ (resp. $\partial K_m^-$) denote the future (resp. past) boundary of $K_m$. Recall that, for all $m$, $\partial K_m^\pm$ is intrinsically hyperbolic, and we denote by $\tau^\pm_m$ the point in Teichm\"uller space that it defines. For all $m$, let $\lambda^\pm_m(\gamma)$ denote the length of the unique geodesic in $\partial K_m^\pm$ in the free homotopy class of $\rho_m(\gamma)$. By \cite[Lemma B.1]{Pro}, for all $m$, and for all $\gamma$,
\begin{equation*}
\lambda_m^+(\gamma)\geq l_{1,m}(\gamma)\qquad\text{and}\qquad\lambda_m^-(\gamma)\geq l_{2,m}(\gamma)\ .
\end{equation*}
By \cite[Lemma 6.1]{Tam}, upon extracting a subsequence if necessary, we may suppose that $(\tau_m^\pm)_{m\in\mathbb{N}}$ subconverges in Teichm\"uller space to some limit $\tau_\infty^\pm$, say. By \cite[Lemma A.2]{BDMS}, $(\rho_m)_{m\in\mathbb{N}}$ therefore subconverges to some limit $\rho_\infty$, say, in $\mathcal{T}\times\mathcal{T}$, and this completes the proof.

For all $m\in\mathbb{N}$, we denote the limit set of $\Lambda_m$ by $\rho_m$. We first show that there exists $B_1>0$ such that, for all $m$, $\Lambda_m$ is $B_1$-quasisymmetric. Indeed, by Lemma \ref{lemma:CompactnessOfRepresentations}, there exists $B_1\geq 1$ such that, for all $m\in\mathbb{N}$,
\begin{equation*}
d_{\mathrm{Lip}}(\rho_{m,r},\rho_{m,l})<\frac{1}{2}\ln(B_1)\ .
\end{equation*}
For all $m\in\mathbb{N}$, let $\phi_m:\mathbb{H}^2\rightarrow\mathbb{H}^2$ be a $\sqrt{B_1}$-bilipschitz, $(\rho_{m,r},\rho_{m,l})$ equivariant homeomorphism, let $\alpha_m:=\partial_\infty\phi_m$ denote its extension to $\partial_\infty\mathbb{H}^2$, and note that $\Lambda_m$ coincides with the graph of $\alpha_m$. For all $m$, since $\phi_m$ is $B_1$-quasiconformal, $\Lambda_m$ is $B_1$-quasisymmetric, as asserted.

The proof of \cite[Lemma 7.11]{BDMS}, carried out there in the case of constant curvature surfaces, adapts to the present case yielding a constant $B_2>0$ such that, for all $i$, and for all $m$,
\begin{equation*}
\|A_{i,m}\| \leq B_2\ ,
\end{equation*}
and the result now follows by \cite[Lemma 4.1]{Smith2021Weyl}.

Indeed, for each $i$, let $\phi_i'$ be a $\sigma_i$-invariant function such that $\phi_i'>1$, and let $u_i'$ denote the unique smooth, $\sigma_i$-invariant function such that $\kappa[u_i']=-\phi_i$. For each $i$, let $(\phi_{i,t})_{t\in[0,1]}$ be a smooth family of smooth, $\sigma_i$-invariant functions such that, for all $t$, $\phi_{i,t}>1$ and
\begin{equation*}
\phi_{i,0}=\phi_i\qquad\text{and}\qquad\phi_{i,1}=\phi_i'\ .
\end{equation*}
For each $i$, and for all $t$, let $u_{i,t}$ denote the unique smooth, $\sigma_i$-invariant solution of $\kappa[u_{i,t}]=-\phi_{i,t}$. For each $i$, let $A_i$ be a $\sigma_i$-invariant $(\phi_i-1)$-Labourie field, and suppose that
\begin{equation*}
\rho^+[u_1,A_1] = \rho^-[u_2,A_2]\ .
\end{equation*}

We claim that $A_1$ and $A_2$ extend to unique continuous families $(A_{1,t})_{t\in[0,1]}$ and $(A_{2,t})_{t\in[0,1]}$ such that
\begin{enumerate}
\item for each $i$, and for all $t$, $A_{i,t}$ is a $\sigma_i$-invariant $(\phi_i-1)$-Labourie field; and
\item for all $t$,
\begin{equation*}
\rho^+[u_{1,t},A_{1,t}] = \rho^-[u_{2,t},A_{2,t}]\ .
\end{equation*}
\end{enumerate}
Indeed, consider the set $\mathcal{T}$ of all $T\in[0,1]$ for which unique extensions satisfying these properties exist over the interval $[0,T]$. By Lemma  \ref{lemma:GlobalCompactness}, this set is closed, and by Lemma \ref{lemma:ContinuityMethodOpenness}, it is open. Since it trivially contains the point $T=0$, it is non-empty, and thus, by connectedness, coincides with the whole of $[0,1]$. This proves the claim.

The result therefore holds for $(\phi_1,\phi_2)$ if and only if it holds for $(\phi_1',\phi_2')$. However, by \cite[Theorem 1.0.2]{cyclic2}, for all constant $k>0$, the result holds for
\begin{equation*}
(\phi_1,\phi_2) = (k+1,1/k+1)\ ,
\end{equation*}
and this completes the proof.

For each $i$, let $\sigma_1:\Pi\rightarrow\mathrm{P}\mathrm{SL}(2,\mathbb{R})$ be a Fuchsian representation such that $S_i$ is conformally equivalent to $\mathbb{D}/\sigma_i(\Pi)$. For each $i$, let $u_i:\mathbb{D}\rightarrow\mathbb{R}$ be a $\sigma_i$-invariant function such that $S_i$ is isometric to $\big(\mathbb{D}/\sigma_i(\Pi),g[u_i]\big)$ and denote $\phi_i:=-\kappa[u_i]$.

By Theorem \ref{thm:ExistenceAndUniquenessForLabourieFields}, there exists a unique pair $(A_1,A_2)$ such that, for each $i$, $A_i$ is a $\sigma_i$-invariant $(\phi_i-1)$-Labourie field, and
\begin{equation*}
\rho^+[u_1,A_1]=\rho^-[u_2,A_2]=:\rho\ .
\end{equation*}
Let $\Lambda$ denote the limit set of $\rho$, let $\Omega$ denote its invisibility domain, and denote
\begin{equation*}
Y:=\mathrm{AdS}^{2,1}/\rho(\Pi)\ .
\end{equation*}

This is a GHMC anti-de Sitter manifold into which $S_1$ (resp. $S_2$) isometrically embeds as a future convex (resp. past convex) smooth, spacelike immersion. The images of $S_1$ and $S_2$ together bound a convex subset $X$ of $Y$, and this proves existence. Since a different representation $\rho'$ necessarily yields a different pair $(A_1',A_2')$ of Labourie fields, it follows that $\rho$ is unique, and therefore so too is $X$. Finally, uniqueness of $(A_1,A_2)$ also implies uniqueness of the embeddings of $S_1$ and $S_2$ into $Y$. It follows that $X$ is indeed unique up to isometries preserving the marking, and this completes the proof.
